93	Field DataTypeAggregateFunction::getDefault() const
94	{
95	    Field field = AggregateFunctionStateData();
96	    field.get<AggregateFunctionStateData &>().name = getName();
97	
98	    AlignedBuffer place_buffer(function->sizeOfData(), function->alignOfData());
99	    AggregateDataPtr place = place_buffer.data();
100	
101	    function->create(place);
102	
103	    try
104	    {
105	        WriteBufferFromString buffer_from_field(field.get<AggregateFunctionStateData &>().data);
106	        function->serialize(place, buffer_from_field, version);
107	    }
108	    catch (...)
109	    {
110	        function->destroy(place);
111	        throw;
112	    }
113	
114	    function->destroy(place);
115	
116	    return field;
117	}
