11	/** Type - the state of the aggregate function.
12	  * Type parameters is an aggregate function, the types of its arguments, and its parameters (for parametric aggregate functions).
13	  *
14	  * Data type can support versioning for serialization of aggregate function state.
15	  * Version 0 also means no versioning. When a table with versioned data type is attached, its version is parsed from AST. If
16	  * there is no version in AST, then it is either attach with no version in metadata (then version is 0) or it
17	  * is a new data type (then version is default - latest).
18	  */
19	class DataTypeAggregateFunction final : public IDataType
20	{
21	private:
22	    AggregateFunctionPtr function;
23	    DataTypes argument_types;
24	    Array parameters;
25	    mutable std::optional<size_t> version;
26	
27	    String getNameImpl(bool with_version) const;
28	    size_t getVersion() const;
29	
30	public:
31	    static constexpr bool is_parametric = true;
32	
33	    DataTypeAggregateFunction(const AggregateFunctionPtr & function_, const DataTypes & argument_types_,
34	                              const Array & parameters_, std::optional<size_t> version_ = std::nullopt)
35	        : function(function_)
36	        , argument_types(argument_types_)
37	        , parameters(parameters_)
38	        , version(version_)
39	    {
40	    }
41	
42	    String getFunctionName() const { return function->getName(); }
43	    AggregateFunctionPtr getFunction() const { return function; }
44	
45	    String doGetName() const override;
46	    String getNameWithoutVersion() const;
47	    const char * getFamilyName() const override { return "AggregateFunction"; }
48	    TypeIndex getTypeId() const override { return TypeIndex::AggregateFunction; }
49	
50	    Array getParameters() const { return parameters; }
51	
52	    bool canBeInsideNullable() const override { return false; }
53	
54	    DataTypePtr getReturnType() const { return function->getReturnType(); }
55	    DataTypePtr getReturnTypeToPredict() const { return function->getReturnTypeToPredict(); }
56	    DataTypes getArgumentsDataTypes() const { return argument_types; }
57	
58	    MutableColumnPtr createColumn() const override;
59	
60	    Field getDefault() const override;
61	
62	    bool equals(const IDataType & rhs) const override;
63	
64	    bool isParametric() const override { return true; }
65	    bool haveSubtypes() const override { return false; }
66	    bool shouldAlignRightInPrettyFormats() const override { return false; }
67	
68	    SerializationPtr doGetDefaultSerialization() const override;
69	    bool supportsSparseSerialization() const override { return false; }
70	
71	    bool isVersioned() const { return function->isVersioned(); }
72	
73	    size_t getVersionFromRevision(size_t revision) const { return function->getVersionFromRevision(revision); }
74	
75	    /// Version is not empty only if it was parsed from AST or implicitly cast to 0 or version according
76	    /// to server revision.
77	    /// It is ok to have an empty version value here - then for serialization a default (latest)
78	    /// version is used. This method is used to force some zero version to be used instead of
79	    /// default, or to set version for serialization in distributed queries.
80	    void setVersion(size_t version_, bool if_empty) const
81	    {
82	        if (version && if_empty)
83	            return;
84	
85	        version = version_;
86	    }
87	};
